local LIGHTS = {
	{ offset = Vector3.new(0, 0, 0), color = Color3.fromHex("#ff8a30"), range = 34, keys = { {0, 0}, {0.01, 6}, {0.15, 4.5}, {0.6, 1.5}, {1, 0} } },
